             float3x3 rgb2yuv = float3x3(
                 0.299,     0.587,    0.114,
                -0.14713,  -0.28886,  0.436,
                 0.615,    -0.51499, -0.10001
            );
             float3x3 yuv2rgb = float3x3(
                1.0,  0.0,      1.13983,
                1.0, -0.39465, -0.58060,
                1.0,  2.03211,  0.0
            );
            float rad = amzp_hue * 0.0174533;
             float3x3 huemat = float3x3(
                1.0,  0.0,       0.0,
                0.0,  cos(rad),  sin(rad),
                0.0,  -sin(rad), cos(rad)
            );

            float4 texColor = amzTexture(0,amzScreenNorm().st);


                    float2 umefx = amzScreenNorm().st;
                    umefx += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;

                    umefx.y -= (umefx.y - 0.5) * 0.7 * fract(amzp_stretch.y * 0.5); 
                    umefx.x -= (umefx.x - 0.5) * 0.7 * fract(amzp_stretch.x * 0.5); 

            float4 baseColor;
            float4 vColor;

            baseColor = amzTexture(0, amzScreenNorm().st)*amzp_calpha;
            vColor = amzTexture(1, amzScreenNorm().st);


            float raddd = amzp_angleee * 0.0174533;
            float adjStrength = amzp_strengthhh / 8.0;
            float2 offset = float2(cos(raddd)*adjStrength,-sin(raddd)*adjStrength);
            offset += float2((0.0+amzp_OFT.x), (0.0+amzp_OFT.y))*float2(-1.,1.)/500.;
            float2 sampleLow = (float4(amzLayerNorm() - offset,0.0,1.0) * amzLayerToScreen()).xy;
            float2 sampleHigh = (float4(amzLayerNorm() + offset,0.0,1.0) * amzLayerToScreen()).xy;
            float4 colorLow = amzTexture(1,sampleLow);
            float4 colorHigh = amzTexture(1,sampleHigh);

            float4 colorMid = amzTexture(1,umefx);


            float4 outColor;
            if( int(amzp_centerChannel)==0 ) {
                outColor = float4(colorMid.r,colorLow.g,colorHigh.b,1.0);
            } else if( int(amzp_centerChannel)==1 ) {
                outColor = float4(colorLow.r,colorMid.g,colorHigh.b,1.0);
            } else {
                outColor = float4(colorLow.r,colorHigh.g,colorMid.b,1.0);
            }

            float4 compColorr;
            float4 gammaComp;

            compColorr = (amzp_CHROM>0.5)? float4(outColor.rgb,colorMid.a) :
                            amzTexture(1, umefx);





            float3 normCol = compColorr.rgb;
            float3 gamcor = pow(normCol, float3(1.0 / 2.2));
            float4 gamcorComp = float4(gamcor, compColorr.a);

            gammaComp = (amzp_GCE>0.5)? gamcorComp*compColorr.a : compColorr;



             float3 rgb = gammaComp.rgb;
             float3 yuv = rgb * rgb2yuv;
            yuv = yuv * huemat; 
            float origSat = min(1.0,length(yuv.yz)*2.5); 
            float2 satUV = yuv.yz * amzp_satvib.y;
            yuv.yz = mix(satUV,yuv.yz,origSat);
            yuv.yz = yuv.yz * (amzp_satvib.x+1.0);
            rgb = yuv * yuv2rgb;

            float4 satComp = float4(rgb, gammaComp.a);


            float4 dblur = float4(satComp.rgb / satComp.a, 1.0);

            float4 targetLuma = dblur ;
            const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (amzp_lowThreshold*(1.0+amzp_feather))-0.0001;
            float lowThresholdA = lowThresholdB-max(amzp_feather,0.00001);
            float highThresholdA = (amzp_highThreshold*(1.0+amzp_feather)-amzp_feather)+0.0001;
            float highThresholdB = highThresholdA+max(amzp_feather,0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            float4 dblurr = targetLuma;
            if (amzp_lowThreshold > 0.001 || amzp_highThreshold < 0.001) { dblurr *= lumafx; }


            dblurr *= satComp.a;
            dblurr *= amzp_oalpha;


            float3 blendGlow;
            if(int(amzp_cmode) == 0) {
            blendGlow = float3(dblurr.rgb+amzp_colblend.rgb); }
            else if(int(amzp_cmode) == 1) {
            blendGlow = float3(amzp_colblend.rgb); }

            float4 mixcblend = mix(dblurr, float4(blendGlow, dblurr.a), amzp_alpb);
            float4 blendComp = (amzp_cblend>0.5)? mixcblend * dblurr.a : dblurr;









            float4 finalGlow;
            if(int(amzp_bmode) == 0) {
            float3 colorScreen = blendScreen(baseColor.rgb, blendComp.rgb);
            finalGlow = newLayer(baseColor, float4(colorScreen.rgb, blendComp.a) ); }


            else if(int(amzp_bmode) == 1) {
            finalGlow = baseColor / (1.0-blendComp); }
            else if(int(amzp_bmode) == 2) {
            finalGlow = baseColor + blendComp; }
            else if(int(amzp_bmode) == 3) {
            finalGlow = newLayer(baseColor, blendComp); }

            amzOutput = amzp_strength > 0.00001? finalGlow : texColor;
            if((amzp_overd>0.5)) { amzOutput *= texColor.a; }

        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

